def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = sum(1 for a in op if a == 'C')
    last_me = me[-1]
    last_op = op[-1]

    recent = op[-5:] if n >= 5 else op
    recent_d = sum(1 for a in recent if a == 'D')

    if recent_d >= 3:
        if last_me == 'D' and last_op == 'D':
            return 'C'
        return 'D'

    if op_c >= n - max(1, n // 10):
        if last_op == 'D':
            if last_me == 'D':
                return 'C'
            return 'D'
        if n > 10 and rng.random() < 0.05:
            return 'D'
        return 'C'

    if op_c <= n // 3:
        if last_me == 'D' and last_op == 'D':
            return 'C'
        if last_op == 'D':
            return 'D'
        return 'C'

    if last_op == 'D':
        if last_me == 'D':
            return 'C'
        if rng.random() < 0.5:
            return 'C'
        return 'D'

    if n > 85:
        return 'D' if rng.random() < 0.35 else 'C'
    return 'C'
